cat > src/uri.js <<'EOF'
export class UriError extends Error {}

export function parse(s) {
  let scheme, authority, query, fragment
  const m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  let i = s.indexOf('#')
  if (i >= 0) { fragment = s.slice(i + 1); s = s.slice(0, i) }
  i = s.indexOf('?')
  if (i >= 0) { query = s.slice(i + 1); s = s.slice(0, i) }
  if (s.startsWith('//')) {
    const rest = s.slice(2)
    const j = rest.search(/\//)
    authority = j < 0 ? rest : rest.slice(0, j)
    s = j < 0 ? '' : rest.slice(j)
  }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo, hostport = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); hostport = a.slice(at + 1) }
  const rb = hostport.lastIndexOf(']')
  const c = hostport.indexOf(':', rb < 0 ? 0 : rb)
  let host = hostport, port
  if (c >= 0) { host = hostport.slice(0, c); port = hostport.slice(c + 1) }
  return { userinfo, host, port }
}

function checkPct(label, v) {
  if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
    throw new UriError(`the ${label} has a truncated percent-encoding`)
  }
}

function check(p) {
  checkPct('path', p.path)
  checkPct('query', p.query)
  checkPct('fragment', p.fragment)
}

function checkAll(p) {
  let ui, host
  if (p.authority !== undefined) ({ userinfo: ui, host } = splitAuthority(p.authority))
  checkPct('userinfo', ui)
  checkPct('host', host)
  checkPct('path', p.path)
  checkPct('query', p.query)
  checkPct('fragment', p.fragment)
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(v) {
  if (v === undefined) return v
  return v.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const lowerHost = (s) => s.split(/(%[0-9A-F]{2})/).map((x, i) => (i % 2 ? x : lowerAscii(x))).join('')

export function removeDots(path) {
  let input = path, out = ''
  while (input) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (input === '.' || input === '..') input = ''
    else {
      const j = input.indexOf('/', 1)
      const seg = j < 0 ? input : input.slice(0, j)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function recompose(p) {
  // p components already syntactically final; normalize
  const scheme = p.scheme === undefined ? undefined : lowerAscii(p.scheme)
  let authority
  if (p.authority !== undefined) {
    const { userinfo, host, port } = splitAuthority(p.authority)
    let pt = pct(port)
    if (pt === '' || (scheme !== undefined && DEFAULT_PORT[scheme] === pt)) pt = undefined
    authority = (userinfo !== undefined ? pct(userinfo) + '@' : '') + lowerHost(pct(host)) + (pt !== undefined ? ':' + pt : '')
  }
  let path = removeDots(pct(p.path))
  if (authority !== undefined && path === '') path = '/'
  let r = ''
  if (scheme !== undefined) r += scheme + ':'
  if (authority !== undefined) r += '//' + authority
  r += path
  if (p.query !== undefined) r += '?' + pct(p.query)
  if (p.fragment !== undefined) r += '#' + pct(p.fragment)
  return r
}

export function normalize(s) {
  const p = parse(s)
  checkAll(p)
  return recompose(p)
}

export function resolve(baseStr, refStr) {
  const b = parse(baseStr)
  if (b.scheme === undefined) throw new UriError('the base has no scheme')
  const r = parse(refStr)
  checkAll(b)
  checkAll(r)
  let t
  if (r.scheme !== undefined) t = { ...r }
  else if (r.authority !== undefined) t = { ...r, scheme: b.scheme }
  else if (r.path === '') {
    t = { scheme: b.scheme, authority: b.authority, path: b.path, query: r.query !== undefined ? r.query : b.query, fragment: r.fragment }
  } else {
    let path
    if (r.path.startsWith('/')) path = r.path
    else if (b.authority !== undefined && b.path === '') path = '/' + r.path
    else {
      const k = b.path.lastIndexOf('/')
      path = k < 0 ? r.path : b.path.slice(0, k + 1) + r.path
    }
    t = { scheme: b.scheme, authority: b.authority, path, query: r.query, fragment: r.fragment }
  }
  return recompose(t)
}
