{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261003T225323Z/cell-5qZexk/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(text, field, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

// Policies: bucket tokens are stored scaled by `per` so fractions stay exact.
function makeState(p) {
  return p.kind === 'bucket' ? { units: p.capacity * p.per, last: null } : { ticks: [] }
}
function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    if (s.last !== null) {
      s.units += p.refill * (tick - s.last)
      const max = p.capacity * p.per
      if (s.units > max) s.units = max
    }
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}
function allows(p, s) {
  return p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
}
function record(p, s, tick) {
  if (p.kind === 'bucket') s.units -= p.per
  else s.ticks.push(tick)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    try {
      const line = lines[i].trim()
      if (line === '' || line.startsWith('#')) continue
      const w = line.split(/\s+/)
      const d = w[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (events.length > 0) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (w.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const capacity = int(w[2], 'capacity', 1)
        const refill = int(w[3], 'refill', 0)
        const per = int(w[4], 'per', 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { kind: 'bucket', name: w[1], capacity, refill, per })
      } else if (d === 'window') {
        if (w.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const limit = int(w[2], 'limit', 0)
        const span = int(w[3], 'span', 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { kind: 'window', name: w[1], limit, span })
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        const list = []
        for (const n of w.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(w[1], list)
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int(w[1], 'tick', 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: w[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

let parsed
try {
  parsed = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

const { routes, events } = parsed
const states = new Map()
const stats = new Map()
const out = []
let ta = 0
let td = 0
for (const { tick, key } of events) {
  let best = null
  for (const prefix of routes.keys()) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
  }
  let denier = null
  if (best !== null) {
    const list = routes.get(best)
    const sts = list.map((p) => {
      const id = `${p.name}\n${key}`
      if (!states.has(id)) states.set(id, makeState(p))
      return states.get(id)
    })
    list.forEach((p, i) => advance(p, sts[i], tick))
    for (let i = 0; i < list.length; i++) {
      if (!allows(list[i], sts[i])) {
        denier = list[i].name
        break
      }
    }
    if (denier === null) list.forEach((p, i) => record(p, sts[i], tick))
  }
  const st = stats.get(key) ?? { a: 0, d: 0 }
  stats.set(key, st)
  if (denier === null) {
    st.a++
    ta++
    out.push(`${tick} ${key} allow`)
  } else {
    st.d++
    td++
    out.push(`${tick} ${key} deny ${denier}`)
  }
}
if (mode === 'summary') {
  const keys = [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))
  for (const k of keys) out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  out.length = keys.length
  out.push(`total allowed=${ta} denied=${td}`)
  out.splice(0, out.length - keys.length - 1)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

