const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'normalize' && mode[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  const r = { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
  if (r.authority !== undefined) {
    let a = r.authority
    const at = a.lastIndexOf('@')
    if (at >= 0) { r.userinfo = a.slice(0, at); a = a.slice(at + 1) }
    const rb = a.lastIndexOf(']')
    const colon = a.indexOf(':', rb + 1)
    if (colon >= 0) { r.port = a.slice(colon + 1); a = a.slice(0, colon) }
    r.host = a
  }
  return r
}

function checkPct(r, n) {
  const bad = /%(?![0-9A-Fa-f]{2})/
  for (const [k, v] of [['path', r.path], ['userinfo', r.userinfo], ['host', r.host], ['query', r.query], ['fragment', r.fragment]]) {
    if (v !== undefined && bad.test(v)) throw new Fail(`error: line ${n}: the ${k} has a truncated percent-encoding`)
  }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const pct = (s) => s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
  const c = String.fromCharCode(parseInt(h, 16))
  return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
})

function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
