{"file_path":"src/parse.js","content":"export function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const l = m[1].toUpperCase()
  const col = l.length === 1 ? l.charCodeAt(0) - 64 : 26 + (l.charCodeAt(0) - 65) * 26 + (l.charCodeAt(1) - 64)
  return { col, row }
}

function lex(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns { ast, badRange } or null when the grammar rejects the body.
export function parseFormula(src) {
  const toks = lex(src)
  if (!toks) return null
  let p = 0
  let badRange = false
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const FAIL = {}

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary(argPos) {
    const tk = toks[p]
    if (!tk) throw FAIL
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw FAIL
      p++
      return e
    }
    if (tk.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) throw FAIL
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw FAIL
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const up = tk.v.toUpperCase()
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') throw FAIL
        p++
        return { t: 'range', a: parseAddr(tk.v), b: parseAddr(t2.v) }
      }
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', addr: parseAddr(tk.v) }
    }
    throw FAIL
  }
  function arg() {
    const e = cmp()
    return e
  }
  function check(n, direct) {
    if (n.t === 'range') { if (!direct) badRange = true }
    else if (n.t === 'bin') { check(n.l, false); check(n.r, false) }
    else if (n.t === 'un') check(n.e, false)
    else if (n.t === 'call') for (const a of n.args) check(a, true)
  }
  try {
    const ast = cmp()
    if (p < toks.length) return null
    check(ast, false)
    return { ast, badRange }
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (e) => ({ e })
const isErr = (v) => typeof v === 'object' && v !== null && 'e' in v

export function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const x = c - 27
  return String.fromCharCode(65 + Math.floor(x / 26)) + String.fromCharCode(65 + (x % 26))
}

function fmt(v) {
  if (isErr(v)) return v.e
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

function cpCompare(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

export function evaluateAll(cells) {
  const memo = new Map()
  const busy = new Set()
  const result = new Map()

  function cellValue(col, row) {
    const key = col * 1000 + row
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return 0
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    let v
    const s = c.content
    if (s[0] === '=') {
      const p = parseFormula(s.slice(1))
      if (!p || p.badRange) v = err('#ERR!')
      else v = ev(p.ast)
    } else if (s === '') v = 0
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = Number(s)
    else if (ERRORS.has(s)) v = err(s)
    else v = s
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function num(v) {
    if (typeof v === 'number') return v
    if (typeof v === 'boolean') return v ? 1 : 0
    return err('#VALUE!')
  }
  function fin(x) {
    return Number.isFinite(x) ? x : err('#DIV/0!')
  }
  function rangeVals(n) {
    if (!n.a || !n.b) return [err('#REF!')]
    const out = []
    for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
      for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) out.push(cellValue(c, r))
    return out
  }
  function single(n) {
    if (n.t !== 'range') return ev(n)
    const vs = rangeVals(n)
    const e = vs.find(isErr)
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }
  const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

  function ev(n) {
    switch (n.t) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'ref': return n.addr ? cellValue(n.addr.col, n.addr.row) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const v = ev(n.e)
        if (isErr(v)) return v
        const x = num(v)
        if (isErr(x)) return x
        return n.op === '-' ? fin(-x) : x
      }
      case 'bin': {
        const l = ev(n.l)
        if (isErr(l)) return l
        const r = ev(n.r)
        if (isErr(r)) return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          let c
          const rl = rank(l), rr = rank(r)
          if (rl !== rr) c = rl < rr ? -1 : 1
          else if (rl === 0) c = l < r ? -1 : l > r ? 1 : 0
          else if (rl === 1) c = cpCompare(l, r)
          else c = l === r ? 0 : l ? 1 : -1
          switch (n.op) {
            case '=': return c === 0
            case '<>': return c !== 0
            case '<': return c < 0
            case '<=': return c <= 0
            case '>': return c > 0
            default: return c >= 0
          }
        }
        const a = num(l)
        if (isErr(a)) return a
        const b = num(r)
        if (isErr(b)) return b
        switch (n.op) {
          case '+': return fin(a + b)
          case '-': return fin(a - b)
          case '*': return fin(a * b)
          case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
          default: return fin(Math.pow(a, b))
        }
      }
      case 'call': return call(n)
    }
  }

  function call(n) {
    const name = n.name
    const args = n.args
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const c = single(args[0])
      if (isErr(c)) return c
      let t
      if (typeof c === 'boolean') t = c
      else if (typeof c === 'number') t = c !== 0
      else return err('#VALUE!')
      return single(args[t ? 1 : 2])
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const v = single(args[0])
      if (isErr(v)) return v
      const x = num(v)
      return isErr(x) ? x : fin(Math.abs(x))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (args.length < 1) return err('#ERR!')
    const vals = []
    for (const a of args) {
      if (a.t === 'range') vals.push(...rangeVals(a))
      else vals.push(ev(a))
    }
    const e = vals.find(isErr)
    if (e) return e
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = num(v)
      if (isErr(x)) return x
      nums.push(x)
    }
    let r
