    if (!tasks.has(name)) throw new GraphError(`error: unknown task ${name}`)
  }
  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, [...(depSets.get(name) ?? [])].sort())
  return { tasks, deps }
}
