export function findCycle({ tasks, deps }) {
  const state = new Map()
  const stack = []
  function visit(n) {
    state.set(n, 1)
    stack.push(n)
    for (const d of deps.get(n)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
  }
  for (const n of [...tasks.keys()].sort()) {
    if (!state.get(n)) {
      const c = visit(n)
      if (c) return c
    }
  }
  return null
}

function topo({ tasks, deps }) {
  const order = []
  const seen = new Set()
  const go = (n) => {
    if (seen.has(n)) return
    seen.add(n)
    for (const d of deps.get(n)) go(d)
    order.push(n)
  }
  for (const n of [...tasks.keys()].sort()) go(n)
  return order
}

export function schedule(graph) {
  const info = new Map()
  let total = 0n
  for (const n of topo(graph)) {
    let start = 0n
    let depth = 0
    for (const d of graph.deps.get(n)) {
      const i = info.get(d)
      if (i.finish > start) start = i.finish
      if (i.depth + 1 > depth) depth = i.depth + 1
    }
    const finish = start + graph.tasks.get(n)
    info.set(n, { start, finish, depth })
    if (finish > total) total = finish
  }
  return { info, total }
}

export function packWorkers(graph, workers) {
  const { tasks, deps } = graph
  const order = topo(graph)
  const prio = new Map()
  const dependents = new Map([...tasks.keys()].map((n) => [n, []]))
  for (const [n, ds] of deps) for (const d of ds) dependents.get(d).push(n)
  for (const n of [...order].reverse()) {
    let best = 0n
    for (const m of dependents.get(n)) if (prio.get(m) > best) best = prio.get(m)
    prio.set(n, best + tasks.get(n))
  }
  const finish = new Map()
  const pending = new Set(tasks.keys())
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const n of pending) {
        if (!deps.get(n).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick) || (prio.get(n) === prio.get(pick) && n < pick)) pick = n
      }
      if (pick === null) break
      const f = t + tasks.get(pick)
      pending.delete(pick)
      finish.set(pick, f)
      freeAt[w] = f
      ran[w].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  const lines = ran.map((r, i) => `worker ${i}:` + r.map((x) => ' ' + x).join(''))
  return { lines, makespan }
}
"}

