{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(cmp)
}

function render(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node)
      if (ks.length === 0) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${render(node.map.get(k), indent + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'aot':
    case 'array': {
      if (node.items.length === 0) return '[]'
      return '[\n' + node.items.map((i) => pad + render(i, indent + 1)).join(',\n') + '\n' + end + ']'
    }
    default:
      return JSON.stringify(node.v)
  }
}

export function toJson(root) {
  return render(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === '' ? k : path + '.' + k
        const c = node.map.get(k)
        lines.push(`${p} ${typeName(c)}`)
        walk(c, p)
      }
    } else if (node.t === 'aot' || node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${typeName(c)}`)
        walk(c, p)
      })
    }
  }
  walk(root, '')
  return lines.map((l) => l + '\n').join('')
}

function typeName(n) {
  return n.t === 'aot' ? 'array' : n.t
}
