  const names = parseDotted(L)
  L.ws()
  const closeErr = () => fail('unterminated table header')
  if (L.peek() !== ']') closeErr()
  L.i++
  if (isArr) {
    if (L.peek() !== ']') closeErr()
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  const parent = walk(root, [], names, names.length - 1)
  const last = names[names.length - 1]
  const full = names.join('.')
  const ex = parent.map.get(last)
  if (isArr) {
    if (ex === undefined) {
      const t = newTable()
      t.header = true
      parent.map.set(last, { t: 'aot', items: [t] })
      return t
    }
    if (ex.t !== 'aot') fail(full + ' is not an array of tables')
    const t = newTable()
    t.header = true
    ex.items.push(t)
    return t
  }
  if (ex === undefined) {
    const t = newTable()
    t.header = true
    parent.map.set(last, t)
    return t
  }
  if (ex.t !== 'table') fail(full + ' is not a table')
  if (ex.header) fail(`table ${full} is defined twice`)
  ex.header = true
  return ex
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
