    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => alive.has(p))
      if (c !== undefined) {
        counts.set(c, counts.get(c) + b.count)
        active += b.count
      }
    }
    history.push(counts)
    const exhausted = ballots.reduce((s, b) => s + b.count, 0n) - active
    const order = [...alive].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
    out.push(`round ${k}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${exhausted}`)
    if (active === 0n) break
    const top = order.find((c) => counts.get(c) * 2n > active)
    if (top !== undefined) { winner = top; break }
    let set = [...alive]
    const min0 = set.reduce((m, c) => (counts.get(c) < m ? counts.get(c) : m), counts.get(set[0]))
    set = set.filter((c) => counts.get(c) === min0)
    for (let r = 0; r < history.length && set.length > 1; r++) {
      const vals = set.map((c) => history[r].get(c))
      const m = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some((v) => v !== m)) set = set.filter((c) => history[r].get(c) === m)
    }
    const gone = set.reduce((a, b) => (b > a ? b : a))
    alive.delete(gone)
    out.push(`eliminated ${gone}`)
