        const per = int(t[4], 'per', 1)
        if (policies.has(t[1])) throw `policy ${t[1]} is declared twice`
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per, state: new Map() })
      } else if (d === 'window') {
        if (t.length !== 4) throw 'expected window <name> <limit> <span>'
        if (!NAME.test(t[1])) throw `invalid policy name ${t[1]}`
        const limit = int(t[2], 'limit', 0)
        const span = int(t[3], 'span', 1)
        if (policies.has(t[1])) throw `policy ${t[1]} is declared twice`
        policies.set(t[1], { kind: 'window', name: t[1], limit, span, state: new Map() })
      } else if (d === 'route') {
        if (t.length < 3) throw 'expected route <prefix> <policy>...'
        if (!NAME.test(t[1])) throw `invalid route prefix ${t[1]}`
        if (routes.has(t[1])) throw `prefix ${t[1]} is routed twice`
        const ps = t.slice(2).map((n) => {
          if (!policies.has(n)) throw `unknown policy ${n}`
          return policies.get(n)
        })
        routes.set(t[1], ps)
      } else {
        if (t.length !== 3) throw 'expected event <tick> <key>'
        const tick = int(t[1], 'tick', 0)
        if (!NAME.test(t[2])) throw `invalid key ${t[2]}`
