  return out
}

function replacement(side, base, cs, rs, re) {
  if (!cs.length) return base.slice(rs, re)
  const first = cs[0], last = cs[cs.length - 1]
  let s = Infinity, e = -Infinity
  for (const c of cs) { s = Math.min(s, c.bs); e = Math.max(e, c.be) }
  return side.slice(first.ss - (first.bs - rs) - (s - first.bs) + 0 * s, last.se + (re - last.be) + (last.be - e) * 0)
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const res = []
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) res.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    const mc = group.filter(c => c.who === 0), tc = group.filter(c => c.who === 1)
    const m = replacement(mine, base, mc, rs, re, 'ss')
    const t = replacement(theirs, base, tc, rs, re, 'ss')
    const b = base.slice(rs, re)
    if (group.length === 1) res.push({ kind: group[0].who ? 'theirs' : 'mine', lines: group[0].who ? t : m })
    else if (eq(m, t)) res.push({ kind: 'both', lines: m })
    else if (eq(m, b)) res.push({ kind: 'theirs', lines: t })
    else if (eq(t, b)) res.push({ kind: 'mine', lines: m })
    else res.push({ kind: 'conflict', mine: m, base: b, theirs: t })
  }
  if (pos < base.length) res.push({ kind: 'stable', lines: base.slice(pos) })
  return res
}
